import type { FoundryContextOption } from "../../../types/foundry";
import { HANDBOOK_TEST_OPTION } from "./constants";

const MUTATING_OPTION_KEYS = [
  "CHATOPT.UseFortuneReroll",
  "CHATOPT.Reroll",
  "CHATOPT.UseFortuneSL",
  "CHATOPT.DarkDeal",
  "CHATOPT.StartOpposed",
  "CHATOPT.DefendOpposed",
  "CHATOPT.CompleteUnopposed",
  "CHATOPT.EditTest",
];

function isHandbookTest(target: HTMLElement): boolean {
  const messageId = target.dataset["messageId"];
  const test = messageId ? game?.messages.get(messageId)?.system.test : undefined;
  return test?.options[HANDBOOK_TEST_OPTION] === true;
}

function suppressForHandbookTest(option: FoundryContextOption): void {
  const originalCondition = option.condition;
  option.condition = (target) => {
    if (isHandbookTest(target)) {
      return false;
    }

    return originalCondition ? originalCondition(target) : true;
  };
}

export function registerHandbookTestContextOptions(): void {
  Hooks.on("getChatMessageContextOptions", (_html, options) => {
    if (!game) {
      return;
    }

    const mutatingOptionNames = new Set(MUTATING_OPTION_KEYS.map((key) => game.i18n.localize(key)));

    for (const option of options) {
      if (mutatingOptionNames.has(option.name)) {
        suppressForHandbookTest(option);
      }
    }
  });
}
