import type { WfrpCharacterModel } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { useMutantsHandbookMutations } from "../../settings";
import { checkMutantsHandbookCorruption } from "./check";
import { reportMutationError } from "./messages";

const replacementMarker = Symbol.for(`${MODULE_ID}.mutantsHandbookReplacement`);

export function installMutantsHandbookReplacement(): void {
  const prototype = CONFIG.Actor.dataModels.character.prototype;

  if (prototype[replacementMarker] === true) {
    return;
  }

  const originalCheckCorruption = prototype.checkCorruption;

  if (typeof originalCheckCorruption !== "function") {
    throw new Error("WFRP4e's character corruption check is unavailable.");
  }

  Object.defineProperty(prototype, replacementMarker, { value: true });
  prototype.checkCorruption = async function (this: WfrpCharacterModel): Promise<void> {
    if (!useMutantsHandbookMutations()) {
      await originalCheckCorruption.call(this);
      return;
    }

    try {
      await checkMutantsHandbookCorruption(this.parent);
    } catch (error) {
      reportMutationError(error);
    }
  };
}
